1	// T47: the landing page's data helper renders the table straight from a review file.
2	// Fixtures are the real published review (reports/rajkaria__roster/review.json) and clones of it with fields overridden.
3	import { describe, expect, test } from "bun:test";
4	import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
5	import { tmpdir } from "node:os";
6	import { join } from "node:path";
7	import type { Review } from "../web/lib/types.ts";
8	
9	const ROOT = join(import.meta.dir, "..");
10	
11	// The root tsconfig has no jsx setting, so it cannot resolve a .tsx import statically. Bun loads it at runtime.
12	interface LandingRow { setup_id: string; label: string; sessions: number; spend: string; unattended: string }
13	const HELPER = join(ROOT, "web", "components", "LandingData.tsx");
14	const { forwardStarted, landingRows, landingTotals }: {
15	  forwardStarted: (dataDir: string) => boolean;
16	  landingRows: (review: Review) => LandingRow[];
17	  landingTotals: (review: Review) => { sessions: number; spend: string };
18	} = await import(HELPER);
19	const REAL = join(ROOT, "reports", "rajkaria__roster", "review.json");
20	const load = (): Review => JSON.parse(readFileSync(REAL, "utf8"));
21	
22	describe("landingRows", () => {
23	  test("one row per setup, in file order, with sessions and spend from the file", () => {
24	    const review = load();
25	    const rows = landingRows(review);
26	    expect(rows.length).toBe(review.setups.length);
27	    rows.forEach((r, i) => {
28	      const s = review.setups[i]!;
29	      expect(r.setup_id).toBe(s.setup_id);
30	      expect(r.label).toBe(s.label);
31	      expect(r.sessions).toBe(s.sessions);
32	      if (s.spend_usd === null) expect(r.spend).toStartWith("unknown");
33	      else expect(r.spend).toBe(`${s.spend_lower_bound ? "≥ " : ""}$${s.spend_usd.toFixed(2)}`);
34	      if (s.mature_sessions === 0) expect(r.unattended).toBe("too young");
35	    });
36	  });
37	
38	  test("unknown spend is never shown as $0", () => {
39	    const review = load();
40	    const s = { ...review.setups[0]!, spend_usd: null, priced_sessions: 1, sessions: 3 };
41	    const [row] = landingRows({ ...review, setups: [s] });
42	    expect(row!.spend).toBe("unknown (1/3 priced)");
43	    expect(landingTotals({ ...review, setups: [s, ...review.setups.slice(1)] }).spend).toStartWith("unknown");
44	  });
45	
46	  test("mature setups show unattended as a percentage", () => {
47	    const review = load();
48	    const s = { ...review.setups[0]!, mature_sessions: 4, unattended: 0.25 };
49	    expect(landingRows({ ...review, setups: [s] })[0]!.unattended).toBe("25%");
50	  });
51	});
52	
53	describe("landingTotals", () => {
54	  test("sums sessions and spend across setups", () => {
55	    const review = load();
56	    const t = landingTotals(review);
57	    expect(t.sessions).toBe(review.setups.reduce((n, s) => n + s.sessions, 0));
58	    const usd = review.setups.reduce((n, s) => n + (s.spend_usd ?? 0), 0);
59	    const lower = review.setups.some((s) => s.spend_lower_bound);
60	    expect(t.spend).toBe(`${lower ? "≥ " : ""}$${usd.toFixed(2)}`);
61	  });
62	});
63	
64	describe("forwardStarted", () => {
65	  test("false until self/forward.json exists", () => {
66	    const dir = mkdtempSync(join(tmpdir(), "roster-landing-"));
67	    try {
68	      expect(forwardStarted(dir)).toBe(false);
69	      mkdirSync(join(dir, "self"));
70	      writeFileSync(join(dir, "self", "forward.json"), "[]");
71	      expect(forwardStarted(dir)).toBe(true);
72	    } finally {
73	      rmSync(dir, { recursive: true, force: true });
74	    }
75	  });
76	});
77	
78	describe("page source", () => {
79	  test("no number literals in the landing page or its sections", () => {
80	    for (const f of ["web/app/page.tsx", "web/components/LandingSections.tsx"]) {
81	      const src = readFileSync(join(ROOT, f), "utf8");
82	      expect(src.match(/\b\d+(\.\d+)?\b/g)).toBeNull();
83	    }
84	  });
85	
86	  test("no em dashes in landing copy", () => {
87	    for (const f of ["web/app/page.tsx", "web/components/LandingSections.tsx", "web/components/LandingData.tsx"]) {
88	      expect(readFileSync(join(ROOT, f), "utf8")).not.toContain("—");
89	    }
90	  });
91	});
92

