export function createLimiter(opts: { perMinute: number }): { take(key: string, now: number): boolean } {
  const capacity = Math.max(0, opts.perMinute);
  const ratePerMs = capacity / 60_000;
  const buckets = new Map<string, { tokens: number; last: number }>();
  return {
    take(key: string, now: number): boolean {
      const b = buckets.get(key) ?? { tokens: capacity, last: now };
      const refill = Math.max(0, now - b.last) * ratePerMs;
      b.tokens = Math.min(capacity, b.tokens + refill);
      b.last = now;
      b.tokens -= 1;
      buckets.set(key, b);
      return b.tokens >= -1e-9;   // careful with float
    },
  };
}
```
